query OneTimePaymentStored($query: SqlQuery, $limit: Int) {
    transactions(query: $query, limit: $limit) {
      items {
        transaction_id
        merchant_uid
        gross_amount
        currency
        status
        account_code
        reference
        metadata
      }
      total_row_count
    }
  }

mutation CreateRefund(
  $transaction_id: String!
  $amount: Int!
  $refund_reason: RefundReasonInput!
) {
  createRefund(
    transaction_id: $transaction_id
    amount: $amount
    refund_reason: $refund_reason
  )
}

query ReversalTransaction($query: SqlQuery, $limit: Int) {
    transactions(query: $query, limit: $limit) {
      items {
        transaction_id
        merchant_uid
        status
        is_settled
        refunded_amount
        gross_amount
        transaction_type
        parent_id
      }
      total_row_count
    }
  }

